  stat.polygon('690,' + cy + ' 678,' + (cy - 6) + ' 678,' + (cy + 6)).fill('#111');
  stat.line(cx, 700, cx, 30).stroke({ color: '#111', width: 1.6 });
  stat.polygon(cx + ',30 ' + (cx - 6) + ',42 ' + (cx + 6) + ',42').fill('#111');

