  var cap1 = stat.text('');
  cap1.move(170, 762).font({ family: SERIF, size: 22, fill: '#222' });
  cap1.tspan('As ');
  cap1.tspan('x').font({ style: 'italic' });
  cap1.tspan(' approaches ');
  cap1.tspan('c').font({ style: 'italic' });
  cap1.tspan(' the point');
  var cap2 = stat.text('');
  cap2.move(170, 794).font({ family: SERIF, size: 22, fill: '#222' });
