      dyn.polyline(arcPts(95, 0, c, 50)).fill('none').stroke({ color: '#222', width: 1.2 });
      halo(dyn.text('c').move(cx + 118 * Math.cos(c / 2) - 5, cy - 118 * Math.sin(c / 2) - 8)
