      .tspan('(cos ').tspan('c').font({ style: 'italic' }).tspan(', sin ').tspan('c').font({ style: 'italic' }).tspan(')');
    halo(dyn.text('').move(toX(x) + 16, toY(x) - 8).font({ family: SERIF, size: 23, fill: '#111' }))
      .tspan('P').font({ style: 'italic' })
      .tspan('(cos ').tspan('x').font({ style: 'italic' }).tspan(', sin ').tspan('x').font({ style: 'italic' }).tspan(')');

