(function () {
  var W = 680, H = 820;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var cx = 200, cy = 340, R = 210;
  function toX(a) { return cx + R * Math.cos(a); }
  function toY(a) { return cy - R * Math.sin(a); }
  var SERIF = "Georgia, 'Times New Roman', serif";

  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    return t;
  }
  // Build a text element from [string, italicFlag] parts, always chaining
  // .tspan() on the PARENT text node (never on a .font() result).
  function label(parent, x, y, size, parts) {
    var t = parent.text('');
    t.move(x, y).font({ family: SERIF, size: size, fill: '#111' });
    for (var i = 0; i < parts.length; i++) {
      var ts = t.tspan(parts[i][0]);
      if (parts[i][1]) ts.font({ style: 'italic' });
    }
    return halo(t);
  }
  function arcPts(r, a0, a1, n) {
    var s = [];
    for (var i = 0; i <= n; i++) {
      var a = a0 + (a1 - a0) * i / n;
      s.push((cx + r * Math.cos(a)).toFixed(2) + ',' + (cy - r * Math.sin(a)).toFixed(2));
    }
    return s.join(' ');
  }

  // ---- radial gradient for the sector ----
  var grad = draw.gradient('radial', function (add) {
    add.stop(0, '#f3e8f6');
    add.stop(0.55, '#d3aede');
    add.stop(1, '#a877bd');
  });
  grad.attr({ cx: cx, cy: cy, r: R, gradientUnits: 'userSpaceOnUse' });

  // ---- static layer ----
  var stat = draw.group();
  // axes
  stat.line(70, cy, 650, cy).stroke({ color: '#111', width: 1.6 });
  stat.polygon('650,' + cy + ' 638,' + (cy - 6) + ' 638,' + (cy + 6)).fill('#111');
  stat.line(cx, 700, cx, 28).stroke({ color: '#111', width: 1.6 });
  stat.polygon(cx + ',28 ' + (cx - 6) + ',40 ' + (cx + 6) + ',40').fill('#111');
  // unit circle: right solid, far-left dashed
  stat.polyline(arcPts(R, -1.95, 1.95, 140)).fill('none')
    .stroke({ color: '#2aa0d8', width: 2.4, linecap: 'round' });
  stat.polyline(arcPts(R, 1.95, 2 * Math.PI - 1.95, 100)).fill('none')
    .stroke({ color: '#2aa0d8', width: 2.4, dasharray: '9,7', linecap: 'round' });
  // caption box + two caption lines
  stat.rect(110, 718, 460, 92).fill('#fff').stroke({ color: '#9aa0a6', width: 2 });
  label(stat, 132, 740, 22, [['As ', 0], ['x', 1], [' approaches ', 0], ['c', 1], [' the point', 0]]);
  label(stat, 132, 774, 22, [['P', 1], [' approaches the point ', 0], ['Q', 1], ['.', 0]]);

  // ---- dynamic layer ----
  var dyn = draw.group();
  var curX = 0.4, curC = 1.0;

  function render() {
    dyn.clear();
    var x = curX, c = curC;
    var lo = Math.min(x, c), hi = Math.max(x, c);

    // shaded sector origin -> arc(lo..hi) -> origin
    var d = 'M ' + cx + ' ' + cy + ' L ' + toX(lo).toFixed(2) + ' ' + toY(lo).toFixed(2);
    var n = 64;
    for (var i = 1; i <= n; i++) {
      var a = lo + (hi - lo) * i / n;
      d += ' L ' + toX(a).toFixed(2) + ' ' + toY(a).toFixed(2);
    }
    d += ' Z';
    dyn.path(d).fill(grad).stroke({ color: '#7a4f8a', width: 0.6, opacity: 0.5 });

    // radii
    dyn.line(cx, cy, toX(c), toY(c)).stroke({ color: '#222', width: 1.6 });
    dyn.line(cx, cy, toX(x), toY(x)).stroke({ color: '#e03131', width: 1.6 });

    // angle arcs + labels
    if (c > 0.03) {
      dyn.polyline(arcPts(96, 0, c, 50)).fill('none').stroke({ color: '#222', width: 1.2 });
      label(dyn, cx + 120 * Math.cos(c / 2) - 6, cy - 120 * Math.sin(c / 2) - 8, 22, [['c', 1]]);
    }
    if (x > 0.03) {
      dyn.polyline(arcPts(58, 0, x, 40)).fill('none').stroke({ color: '#222', width: 1.2 });
      label(dyn, cx + 78 * Math.cos(x / 2) - 4, cy - 78 * Math.sin(x / 2) - 6, 20, [['x', 1]]);
