    // curved approach arrow just outside the circle near Q
    var a0 = c - 0.42, a1 = c - 0.07;
    dyn.polyline(arcPts(R + 22, a0, a1, 30)).fill('none')
      .stroke({ color: '#111', width: 1.6, linecap: 'round' });
    var ae = a1, Ex = cx + (R + 22) * Math.cos(ae), Ey = cy - (R + 22) * Math.sin(ae);
    var Tx = -Math.sin(ae), Ty = -Math.cos(ae);
    var Px = Math.cos(ae), Py = -Math.sin(ae);
    dyn.line(Ex, Ey, Ex - 11 * Tx + 6 * Px, Ey - 11 * Ty + 6 * Py).stroke({ color: '#111', width: 1.6 });
    dyn.line(Ex, Ey, Ex - 11 * Tx - 6 * Px, Ey - 11 * Ty - 6 * Py).stroke({ color: '#111', width: 1.6 });

    // dots
