  }
  function animStep(ts) {
    if (!animOn) return;
    if (!lastTs) lastTs = ts;
    animT += (ts - lastTs) / 1000; lastTs = ts;
    var period = 3.0, p = (animT % period) / period, amp = 0.6, nx;
    if (p < 0.5) { nx = curC - amp * (1 - p / 0.5); }
    else { nx = curC + amp * (1 - (p - 0.5) / 0.5); }
    nx = Math.max(0, Math.min(6.28, nx));
    curX = nx;
    document.getElementById('angleXInput').value = nx.toFixed(2);
    document.getElementById('angleXVal').value = nx.toFixed(2);
    render();
    animRAF = requestAnimationFrame(animStep);
  }

  window.update_angleX = function (v) { stopAnim(); curX = v; render(); };
  window.update_angleC = function (v) { stopAnim(); curC = v; render(); };
  window.trigger_approachAnim = function () {
    if (animOn) { stopAnim(); return; }
    animOn = true; animT = 0; lastTs = 0;
    document.getElementById('approachAnimInput').innerHTML = '&#9632; stop';
    animRAF = requestAnimationFrame(animStep);
  };

  // ---- demo steps ----
  var steps = [
    { title: 'Two angles, one circle', narration: 'A fixed angle c places Q(cos c, sin c) in blue and a variable angle x places P(cos x, sin x) in red; the purple sector between their radii measures the angular gap between them.', state: { angleC: 1, angleX: 0.4 } },
    { title: 'Slide x toward c', narration: 'Drag the x slider up toward c: P travels along the circle toward Q, the red radius rotates onto the dark radius, and the shaded sector shrinks to nothing — the coordinates (cos x, sin x) are converging to (cos c, sin c).', state: { angleC: 1, angleX: 0.95 } },
    { title: 'Move the target c', narration: 'Now drag the c slider to a new angle: Q, both radii, the sector, the angle arcs, and the labels all relocate together, confirming the limit-and-continuity argument works at any c, not just the one pictured.', state: { angleC: 2.4, angleX: 2.35 } },
    { title: 'Approach from both sides', narration: 'Play the animation: x sweeps into c from below and then from above, so P closes on Q from both directions around the circle — exactly the two-sided limit lim_{x→c} that makes sine and cosine continuous everywhere.', state: { angleC: 1, angleX: 1 } }
  ];
  var stepIdx = 0;
  function applyStep(i) {
    stepIdx = i;
    var s = steps[i];
    stopAnim();
    curC = s.state.angleC; curX = s.state.angleX;
    document.getElementById('angleCInput').value = curC.toFixed(2);
    document.getElementById('angleCVal').value = curC.toFixed(2);
    document.getElementById('angleXInput').value = curX.toFixed(2);
    document.getElementById('angleXVal').value = curX.toFixed(2);
    render();
    document.getElementById('demoNarration').textContent = (i + 1) + '. ' + s.title + ' — ' + s.narration;
    document.getElementById('stepLabel').textContent = (i + 1) + '/' + steps.length;
    if (i === steps.length - 1) window.trigger_approachAnim();
  }
  window.nextStep = function () { applyStep((stepIdx + 1) % steps.length); };
  window.prevStep = function () { applyStep((stepIdx - 1 + steps.length) % steps.length); };

  render();
  applyStep(0);
  window.__markRendered();
